  motion(generation: number, pointer: number, gesture: number, x: number, y: number): string;
  /** Complete only the current gesture; invalid endpoints clear its preview. */
  up(generation: number, pointer: number, gesture: number, x: number, y: number): string;
  /** Cancel and clear the current gesture. */
  cancel(generation: number): string;
  /** Permanently close this surface generation. */
  close(generation: number): string;
}

